css:
.briefsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #21262e;
    background: linear-gradient(165deg, #f3f1ec 0%, #ebe7df 100%);
    border-radius: 18px;
}

.briefsim-container * {
    box-sizing: border-box;
}

.briefsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1b2a4a 0%, #243b66 55%, #2f4d80 100%);
    color: #f5f3ee;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(27, 42, 74, 0.30);
    border-bottom: 4px solid #c79a3a;
}

.briefsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.briefsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e6cd8f;
    background: rgba(199, 154, 58, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.briefsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe4ee;
}

.briefsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a4a66;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.briefsim-period-counter #currentDay,
.briefsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b2a4a;
}

.briefsim-round-name {
    background: #e3dccb;
    color: #6b531b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.briefsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4521;
    background: #f6e2d7;
    padding: 4px 12px;
    border-radius: 999px;
}

.briefsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.briefsim-status-card {
    background: #fffdf9;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
    border-top: 4px solid #2f4d80;
}

.briefsim-card-diagnosis { border-top-color: #2f4d80; }
.briefsim-card-design { border-top-color: #1f7a6b; }
.briefsim-card-impact { border-top-color: #8a5cb0; }
.briefsim-card-margin { border-top-color: #c79a3a; }

.briefsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a715f;
}

.briefsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2a4a;
}

.briefsim-card-diagnosis .briefsim-value { color: #2f4d80; }
.briefsim-card-design .briefsim-value { color: #1f7a6b; }
.briefsim-card-impact .briefsim-value { color: #8a5cb0; }
.briefsim-card-margin .briefsim-value { color: #b3851f; }

.briefsim-sublabel {
    font-size: 0.76rem;
    color: #8b8270;
    line-height: 1.35;
}

.briefsim-margin-fail .briefsim-value { color: #c0392b; }
.briefsim-margin-ok .briefsim-value { color: #1f7a6b; }

.briefsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b2a4a;
    color: #f0eee7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.briefsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e6cd8f;
}

.briefsim-budget-over #budgetDisplay {
    color: #ff9b85;
}

.briefsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf9;
    border-left: 5px solid #c79a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.05);
}

.briefsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.briefsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a4a;
    margin-bottom: 6px;
}

.briefsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36404f;
}

.briefsim-briefing-text strong { color: #1f7a6b; }
.briefsim-briefing-text em { color: #9a4521; font-style: italic; }

.briefsim-controls {
    background: #fffdf9;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
}

.briefsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a4a;
    border-bottom: 2px solid #ece6d8;
    padding-bottom: 8px;
}

.briefsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3548;
    margin: 14px 0 6px;
}

.briefsim-container select,
.briefsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3cbb8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #21262e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.briefsim-container select:focus,
.briefsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c79a3a;
    box-shadow: 0 0 0 3px rgba(199, 154, 58, 0.18);
}

.briefsim-container select option {
    background-color: #fffdf9;
    color: #21262e;
}

.briefsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3a;
}

.briefsim-range-readout,
.briefsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #3a4a66;
    margin-top: 4px;
}

.briefsim-range-readout span:last-child,
.briefsim-alloc-readout span:nth-child(2) {
    color: #b3851f;
    font-weight: 800;
}

.briefsim-hint {
    font-size: 0.8rem;
    color: #8b8270;
    margin-top: 4px;
    line-height: 1.4;
}

.briefsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.briefsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f3e9;
    border: 1px solid #e7e0cf;
    border-radius: 9px;
    padding: 8px 12px;
}

.briefsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3548;
}

.briefsim-alloc-row input[type="number"] {
    width: 88px;
    flex: 0 0 88px;
}

.briefsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.briefsim-container .btn-primary {
    background: linear-gradient(135deg, #1b2a4a 0%, #2f4d80 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fdf8ec;
    box-shadow: 0 6px 16px rgba(27, 42, 74, 0.28);
}

.briefsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.briefsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3cbb8;
    color: #7a715f;
}

.briefsim-coach {
    background: #1b2a4a;
    color: #eef1f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 42, 74, 0.22);
    border-left: 5px solid #c79a3a;
}

.briefsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6cd8f;
    margin-bottom: 8px;
}

.briefsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.briefsim-coach-body strong { color: #f4d98c; }
.briefsim-coach-body em { color: #ffc1ad; font-style: italic; }

.briefsim-history,
.briefsim-chart {
    background: #fffdf9;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(27, 42, 74, 0.06);
}

.briefsim-history h3,
.briefsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a4a;
}

.briefsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3548;
}

.briefsim-container table#usfHistoryTable th {
    background: #f1ecdf;
    color: #1b2a4a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2dccd;
}

.briefsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebe0;
}

.briefsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.briefsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .briefsim-container {
        padding: 14px;
    }
    .briefsim-header h1 {
        font-size: 1.7rem;
    }
    .briefsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .briefsim-value {
        font-size: 2rem;
    }
    .briefsim-clock {
        margin-left: 0;
    }
    .briefsim-period-counter {
        font-size: 0.88rem;
    }
    .briefsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .briefsim-alloc-row {
        flex-wrap: wrap;
    }
    .briefsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .briefsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.briefsim-completion { padding: 8px 4px 4px; }
.briefsim-cm-head { text-align: center; margin-bottom: 16px; }
.briefsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a6b; }
.briefsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5c6a86; }
.briefsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #1b2a4a; }
.briefsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.briefsim-cm-yes { background: rgba(31,122,107,0.15); color: #176a5c; border: 1px solid rgba(31,122,107,0.42); }
.briefsim-cm-no { background: rgba(192,57,43,0.12); color: #c0392b; border: 1px solid rgba(192,57,43,0.4); }
.briefsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.briefsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: #f5f8f7; border: 1px solid #d6e2de; border-radius: 10px; padding: 10px 8px; text-align: center; }
.briefsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #1f7a6b; }
.briefsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5c6a86; text-transform: uppercase; letter-spacing: 0.03em; }
.briefsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1b2a4a; }
.briefsim-cm-insights { margin: 0; padding-left: 20px; }
.briefsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #26324a; }

