(function() {
    'use strict';

    class BriefAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The In-Company Brief`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (BRL, millions unless noted).
            this.BUDGET_CEILING = 4.2;      // BRL 4.2M all-in client ceiling
            this.MARGIN_FLOOR = 30;         // 30% contribution-margin staffing floor
            this.UNIT_BENCHMARK = 34;       // unit's FY2025 contribution margin
            this.LOWCOST_BID = 2.5;         // BRL 2.5M low-cost rival
            this.GLOBAL_BID = 5.8;          // BRL 5.8M global-school off-the-shelf
            this.PARTICIPANTS = 180;        // senior + middle managers (→220 in R4)

            // Concept truths — diagnosis before design.
            this.TRUE_PROBLEM = `transformation`;
            this.TRUE_METRIC = `business`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diagnosis: 20,
                    design: 15,
                    impact: 10,
                    margin: this.UNIT_BENCHMARK,   // headline margin %, shown once priced
                    priced: false,                  // becomes true after Round 3
                    proposalCost: 0,                // BRL M committed in proposal
                    participants: this.PARTICIPANTS,
                    marginBroken: false,
                    accountAtRisk: false,
                    diagnosisHistory: [20],
                    designHistory: [15],
                    impactHistory: [10],
                    marginHistory: [this.UNIT_BENCHMARK],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    problem: `transformation`,
                    metric: `business`,
                    recontract: 60,
                    anchor: `frontline`,
                    action: 35,
                    inperson: 30,
                    coaching: 20,
                    digital: 15,
                    measure: `kirkpatrick`,
                    faculty: `blend`,
                    content: `reusecore`,
                    cohort: 6,
                    pricing: `value`,
                    pricecut: `restructure`,
                    scale: `redesign`,
                    facultyplan: `codeliver`,
                    pitch: `outcome`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`problemInput`);
                const me = document.getElementById(`metricInput`);
                const rc = document.getElementById(`recontractInput`);
                if (pr) decisions.problem = pr.value;
                if (me) decisions.metric = me.value;
                if (rc) decisions.recontract = parseInt(rc.value, 10);
                if (!Number.isFinite(decisions.recontract) || decisions.recontract < 0 || decisions.recontract > 100) {
                    warn(`warn_recontract_range`); return false;
                }
            } else if (round === 2) {
                const an = document.getElementById(`anchorInput`);
                const me = document.getElementById(`measureInput`);
                if (an) decisions.anchor = an.value;
                if (me) decisions.measure = me.value;
                const ids = [`actionInput`, `inpersonInput`, `coachingInput`, `digitalInput`];
                const keys = [`action`, `inperson`, `coaching`, `digital`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_mix_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total !== 100) {
                    warn(`warn_mix_total`); return false;
                }
            } else if (round === 3) {
                const fa = document.getElementById(`facultyInput`);
                const co = document.getElementById(`contentInput`);
                const cd = document.getElementById(`cohortInput`);
                const pi = document.getElementById(`pricingInput`);
                if (fa) decisions.faculty = fa.value;
                if (co) decisions.content = co.value;
                if (cd) decisions.cohort = parseInt(cd.value, 10);
                if (pi) decisions.pricing = pi.value;
                if (!Number.isFinite(decisions.cohort) || decisions.cohort < 2 || decisions.cohort > 12) {
                    warn(`warn_cohort_range`); return false;
                }
            } else if (round === 4) {
                const pc = document.getElementById(`pricecutInput`);
                const sc = document.getElementById(`scaleInput`);
                const fp = document.getElementById(`facultyplanInput`);
                const pt = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pc) decisions.pricecut = pc.value;
                if (sc) decisions.scale = sc.value;
                if (fp) decisions.facultyplan = fp.value;
                if (pt) decisions.pitch = pt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let diagDelta = 0, designDelta = 0, impactDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the brief, find the real problem (Common Errors 1 & 2).
                if (d.problem === this.TRUE_PROBLEM) {
                    diagDelta += 30; impactDelta += 8; coachKey = `coach_r1_problem_right`;
                } else if (d.problem === `safety`) {
                    diagDelta += 6; coachKey = `coach_r1_safety`;
                } else if (d.problem === `leadership`) {
                    diagDelta -= 8; impactDelta -= 4; coachKey = `coach_r1_leadership`;
                } else {
                    diagDelta -= 14; impactDelta -= 6; coachKey = `coach_r1_literal`;
                }

                // The board judges business outcomes, not the school's learning metrics.
                if (d.metric === this.TRUE_METRIC) {
                    diagDelta += 12; impactDelta += 10;
                    if (d.problem === this.TRUE_PROBLEM) coachKey = `coach_r1_diag_sharp`;
                } else if (d.metric === `satisfaction`) {
                    impactDelta -= 8; coachKey = `coach_r1_satisfaction`;
                } else {
                    impactDelta -= 4;
                }

                // Courage to reframe and re-contract without losing the client.
                if (d.recontract >= 60) { diagDelta += 8; }
                else if (d.recontract <= 25) { diagDelta -= 10; coachKey = `coach_r1_noreframe`; }

                summaryKey = (d.problem === this.TRUE_PROBLEM && d.metric === this.TRUE_METRIC) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the learning architecture against the diagnosis (Pedagogical Obj. 3).
                if (d.anchor === `frontline`) {
                    designDelta += 16; impactDelta += 10; coachKey = `coach_r2_anchor_right`;
                } else if (d.anchor === `theory`) {
                    designDelta -= 6; impactDelta -= 6; coachKey = `coach_r2_theory`;
                } else {
                    designDelta -= 8; impactDelta -= 4; coachKey = `coach_r2_generic`;
                }

                // 70-20-10 logic: action-learning + peer drive transfer; in-person builds trust;
                // digital reinforces. Lecture-heavy (low action+coaching) does not change behaviour.
                const transfer = d.action + d.coaching;     // social + on-the-job
                const formal = d.inperson;
                if (d.action >= 25 && transfer >= 45 && formal >= 15 && d.digital >= 5) {
                    designDelta += 14; impactDelta += 10; coachKey = `coach_r2_balanced`;
                } else if (transfer < 25) {
                    designDelta -= 10; impactDelta -= 10; coachKey = `coach_r2_lecture`;
                } else if (d.action < 15) {
                    designDelta -= 4; impactDelta -= 4;
                } else {
                    designDelta += 6; impactDelta += 4;
                }
                if (d.digital >= 80) { designDelta -= 8; coachKey = `coach_r2_alldigital`; }

                // Measurement built in from the start (Kirkpatrick L3/L4 vs satisfaction-only).
                if (d.measure === `kirkpatrick`) { designDelta += 8; impactDelta += 12; }
                else if (d.measure === `satisfaction`) { impactDelta -= 6; coachKey = `coach_r2_satisfaction`; }
                else { impactDelta -= 12; designDelta -= 4; coachKey = `coach_r2_nomeasure`; }

                summaryKey = (d.anchor === `frontline` && transfer >= 45 && d.measure === `kirkpatrick`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Price it within the constraint — design and pricing are one decision.
                // Build a cost stack (BRL M) from the choices, then derive margin vs the price.
                // Coefficients are calibrated so the diagnosis-led blend clears the 30% floor near
                // the unit's 34% benchmark, while gold-plating (all-senior + all-bespoke) breaks it.
                let cost = 0.70;                              // base: logistics, platform, overhead share
                if (d.faculty === `blend`) { cost += 0.80; designDelta += 10; impactDelta += 6; coachKey = `coach_r3_facblend`; }
                else if (d.faculty === `allsenior`) { cost += 1.70; designDelta += 6; impactDelta += 4; coachKey = `coach_r3_allsenior`; }
                else { cost += 0.45; designDelta -= 12; impactDelta -= 10; coachKey = `coach_r3_alljunior`; }

                if (d.content === `reusecore`) { cost += 0.35; designDelta += 8; coachKey = (d.faculty === `blend`) ? `coach_r3_smart` : coachKey; }
                else if (d.content === `allbespoke`) { cost += 1.00; designDelta += 4; }
                else { cost += 0.15; designDelta -= 14; impactDelta -= 8; coachKey = `coach_r3_offshelf`; }

                // In-person cohort days: more depth, more cost (faculty + logistics for 180).
                cost += 0.10 * d.cohort;
                if (d.cohort >= 5 && d.cohort <= 8) { designDelta += 6; impactDelta += 4; }
                else if (d.cohort <= 3) { designDelta -= 8; impactDelta -= 6; }
                else if (d.cohort >= 11) { designDelta += 2; }

                // Pricing decision sets the proposal price (revenue).
                let price;
                if (d.pricing === `value`) { price = Math.min(this.BUDGET_CEILING, 4.1); }
                else if (d.pricing === `matchlow`) { price = 2.6; diagDelta -= 6; ds.accountAtRisk = true; coachKey = `coach_r3_matchlow`; }
                else { price = 3.2; designDelta -= 12; impactDelta -= 10; coachKey = `coach_r3_thin`; }

                cost = Math.round(cost * 100) / 100;
                ds.proposalCost = cost;
                const margin = price > 0 ? Math.round(((price - cost) / price) * 1000) / 10 : 0;
                ds.margin = margin;
                ds.priced = true;

                // Margin floor: a beautiful design that breaks 30% is unstaffable (Common Error 3).
                if (margin < this.MARGIN_FLOOR) {
                    ds.marginBroken = true;
                    designDelta -= 10; impactDelta -= 4;
                    coachKey = `coach_r3_marginbreak`;
                } else if (d.pricing === `value` && margin >= this.MARGIN_FLOOR && d.faculty === `blend` && d.content === `reusecore`) {
                    coachKey = `coach_r3_smart`;
                }

                summaryKey = ds.marginBroken ? `sum_r3_break`
                    : (d.pricing === `matchlow` ? `sum_r3_capitulate`
                    : ((d.faculty === `blend` && d.content === `reusecore` && margin >= this.MARGIN_FLOOR) ? `sum_r3_good` : `sum_r3_weak`));
            } else if (round === 4) {
                // Co-create and win — protect design integrity, client, and margin.
                let priceFactor = 1.0;       // multiplier on the current proposal price
                let costFactor = 1.0;        // multiplier on cost (extra participants / coverage)

                // Procurement's 12% price-cut demand.
                if (d.pricecut === `restructure`) { diagDelta += 8; designDelta += 6; priceFactor *= 0.97; costFactor *= 0.94; coachKey = `coach_r4_restructure`; }
                else if (d.pricecut === `hold`) { diagDelta += 4; coachKey = `coach_r4_hold`; }
                else { priceFactor *= 0.88; ds.accountAtRisk = true; diagDelta -= 6; coachKey = `coach_r4_concede`; }

                // +40 participants (→220) inside the same budget (Common Error: absorb silently).
                ds.participants = 220;
                if (d.scale === `redesign`) { designDelta += 8; impactDelta += 6; costFactor *= 1.10; coachKey = (d.pricecut === `restructure`) ? `coach_r4_scale_smart` : coachKey; }
                else if (d.scale === `absorb`) { designDelta -= 10; impactDelta -= 8; coachKey = `coach_r4_absorb`; }
                else { designDelta -= 12; impactDelta -= 12; coachKey = `coach_r4_dilute`; }

                // Lead faculty drops to 50% — re-plan coverage.
                if (d.facultyplan === `codeliver`) { designDelta += 8; impactDelta += 4; costFactor *= 1.05; }
                else if (d.facultyplan === `swap`) { designDelta -= 8; impactDelta -= 6; coachKey = `coach_r4_swap`; }
                else { designDelta -= 10; impactDelta -= 8; coachKey = `coach_r4_cram`; }

                // The 4-minute CHRO pitch — outcome over feature (Common Error 5).
                if (d.pitch === `outcome`) { impactDelta += 16; diagDelta += 6; coachKey = `coach_r4_outcome`; }
                else if (d.pitch === `features`) { impactDelta -= 10; coachKey = `coach_r4_features`; }
                else { impactDelta -= 8; diagDelta -= 6; coachKey = `coach_r4_pricepitch`; }

                // Conviction nudges impact.
                impactDelta += Math.round((d.conviction - 60) / 8);

                // Recompute price, cost and margin under the curveballs.
                const basePrice = Math.min(this.BUDGET_CEILING, 4.1);
                const price = Math.round(basePrice * priceFactor * 100) / 100;
                const cost = Math.round((ds.proposalCost || 2.7) * costFactor * 100) / 100;
                ds.proposalCost = cost;
                const margin = price > 0 ? Math.round(((price - cost) / price) * 1000) / 10 : 0;
                ds.margin = margin;
                ds.priced = true;
                if (margin < this.MARGIN_FLOOR) { ds.marginBroken = true; designDelta -= 6; }
                else { ds.marginBroken = false; }

                summaryKey = (d.pitch === `outcome` && d.scale === `redesign` && !ds.marginBroken && d.pricecut !== `concede`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas (0–100 KPIs).
            ds.diagnosis = Math.max(0, Math.min(100, ds.diagnosis + diagDelta));
            ds.design = Math.max(0, Math.min(100, ds.design + designDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));

            ds.diagnosisHistory.push(Math.round(ds.diagnosis));
            ds.designHistory.push(Math.round(ds.design));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.marginHistory.push(Math.round(ds.margin));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                diagnosis: Math.round(ds.diagnosis),
                diagnosisDelta: Math.round(diagDelta),
                design: Math.round(ds.design),
                designDelta: Math.round(designDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                margin: Math.round(ds.margin),
                proposalCost: ds.proposalCost,
                marginBroken: ds.marginBroken,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
