            }

            // Modality-mix live total.
            const mixIds = [`actionInput`, `inpersonInput`, `coachingInput`, `digitalInput`];
            const mixReadout = document.getElementById(`mixReadout`);
            const recompute = function() {
                let total = 0;
                mixIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (mixReadout) mixReadout.textContent = total;
                const bar = document.querySelector(`.briefsim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            mixIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // Localized chart label with a safe English fallback (chart is built once at load).
        _cl(key, fallback) {
