        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const diagnosis = Math.round(ds.diagnosis || 0);
            const design = Math.round(ds.design || 0);
            const impact = Math.round(ds.impact || 0);
            const margin = Math.round(ds.margin || 0);
            const composite = Math.round(diagnosis * 0.28 + design * 0.26 + impact * 0.26 + Math.min(100, Math.max(0, margin) * 2) * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const diagnosis = Math.round(ds.diagnosis);
            const design = Math.round(ds.design);
            const impact = Math.round(ds.impact);
            const margin = Math.round(ds.margin);

            const marginOk = margin >= this.MARGIN_FLOOR;
            const strongFit = diagnosis >= 65 && design >= 60 && impact >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            let performanceKey = `grade_lost`;
            if (strongFit && marginOk && composite >= 72) performanceKey = `grade_won`;
            else if (strongFit && marginOk) performanceKey = `grade_credible`;
            else if (strongFit && !marginOk) performanceKey = `grade_unstaffable`;
            else if (marginOk && composite >= 55) performanceKey = `grade_generic`;
            else if (ds.accountAtRisk) performanceKey = `grade_battle`;
            const performance = T(performanceKey);

            const insights = [];
            if (strongFit && marginOk) insights.push(window.mySimulation.t(`insight_won`));
            else if (strongFit && !marginOk) insights.push(window.mySimulation.t(`insight_unstaffable`));
            else if (diagnosis < 50) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            else insights.push(window.mySimulation.t(`insight_generic`));

            if (!marginOk) insights.push(window.mySimulation.t(`insight_marginfloor`));
            if (ds.accountAtRisk) insights.push(window.mySimulation.t(`insight_account`));
            if (impact < 45) insights.push(window.mySimulation.t(`insight_featurepitch`));
            if (strongFit && marginOk && composite >= 80) insights.push(window.mySimulation.t(`insight_differentiator`));

            return {
                diagnosis: diagnosis,
                design: design,
                impact: impact,
                margin: margin,
                marginOk: marginOk,
                strongFit: strongFit,
                accountAtRisk: ds.accountAtRisk,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        // v1.1.0: render the computed grade, KPIs and insight debrief in the completion modal
        // instead of the framework generic "you completed N periods" fallback.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.strongFit && s.marginOk);
            const badge = met
                ? `<span class="briefsim-cm-badge briefsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="briefsim-cm-badge briefsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = s.accountAtRisk
                ? ` <span class="briefsim-cm-badge briefsim-cm-no">` + T(`cm_account`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="briefsim-cm-metric"><span class="briefsim-cm-mv">` + Math.round(s.diagnosis || 0) + `</span><span class="briefsim-cm-ml">` + T(`cm_m_diagnosis`) + `</span></div>`
                + `<div class="briefsim-cm-metric"><span class="briefsim-cm-mv">` + Math.round(s.design || 0) + `</span><span class="briefsim-cm-ml">` + T(`cm_m_design`) + `</span></div>`
                + `<div class="briefsim-cm-metric"><span class="briefsim-cm-mv">` + Math.round(s.impact || 0) + `</span><span class="briefsim-cm-ml">` + T(`cm_m_impact`) + `</span></div>`
                + `<div class="briefsim-cm-metric"><span class="briefsim-cm-mv">` + Math.round(s.margin || 0) + `%</span><span class="briefsim-cm-ml">` + T(`cm_m_margin`) + `</span></div>`;
            return ``
                + `<div class="briefsim-completion">`
                +   `<div class="briefsim-cm-head">`
                +     `<div class="briefsim-cm-score">` + score + `<span class="briefsim-cm-score-max">/100</span></div>`
                +     `<div class="briefsim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="briefsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="briefsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="briefsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

